<?php
/** Shared editorial card. Core attachment HTML is generated by WordPress. */
defined( 'ABSPATH' ) || exit;
$story = $args['story'] ?? null;
if ( ! $story instanceof WP_Post ) { return; }
$id = $story->ID;
$title = get_the_title( $story );
$url = get_permalink( $story );
$category = cyberdat_editorial_category( $id );
?>
<article class="editorial-card" data-post-id="<?php echo esc_attr( $id ); ?>"><a class="editorial-image" href="<?php echo esc_url( $url ); ?>" tabindex="-1" aria-hidden="true"><?php echo cyberdat_section_image( $id ); // Trusted WordPress attachment HTML or escaped local fallback. ?></a><div class="editorial-card-body"><div class="story-meta"><span><?php echo esc_html( $category ); ?></span><?php if ( defined( 'CYBERDAT_PLAYGROUND' ) && CYBERDAT_PLAYGROUND ) : ?><span class="sample-label">SAMPLE</span><?php endif; ?></div><h3><a href="<?php echo esc_url( $url ); ?>"><?php echo esc_html( $title ); ?></a></h3><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( get_the_excerpt( $story ) ), 22 ) ); ?></p><div class="card-bottom"><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C, $story ) ); ?>"><?php echo esc_html( get_the_date( 'M j, Y', $story ) ); ?></time><a href="<?php echo esc_url( $url ); ?>" aria-label="<?php echo esc_attr( sprintf( /* translators: %s: Article title. */ __( 'Read: %s', 'cyberdat' ), $title ) ); ?>">↗</a></div></div></article>
